import{_ as t,o as r,c as s,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-05-04","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-05-04","date":"2021-05-04T00:00:00.000Z","updated":"2021-05-05T00:00:00.000Z","tags":["Ceph","分布式存储","自动化","容器化","Kubernetes"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-05-04.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-05-04.md","lastUpdated":1780459816000}'),p={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-05-04.md"};function n(i,e,a,l,_,c){return r(),s("div",null,[...e[0]||(e[0]=[o("<p>本次Ceph Orchestrator Meeting于2021年5月4日举行，会议主要讨论了以下议题：</p><ol><li><p><strong>Quincy项目中的自我管理代理（Self Adm Agent）改进</strong>：讨论了如何使自我管理代理更加工程化和优化，决定召开专门会议进行深入研究和实施计划。</p></li><li><p><strong>容器化Ceph部署</strong>：探讨了使用容器化方法部署Ceph，特别是通过Docker in Docker方法，并考虑将其纳入Ceph的代码库中。</p></li><li><p><strong>服务规范中的容器图像属性移除</strong>：讨论了从服务规范中移除容器图像属性的必要性和方法，决定移除除Ingress和自定义容器服务外的所有容器图像属性。</p></li><li><p><strong>NFS服务的改进</strong>：讨论了NFS服务的部署和管理，特别是在Kubernetes环境中的使用，决定简化NFS集群的创建过程，并在Rook模块中实现Ingress支持。</p></li><li><p><strong>资源限制的自动调整</strong>：讨论了如何自动调整OSD的内存和CPU资源限制，决定使用Ceph的配置选项来管理内存目标。</p></li></ol><p>会议还讨论了其他事项，包括会议安排、特别感谢等。会议纪要涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。具体的日期和人员名单需要根据实际情况填写。</p><p>改进点：</p><ol><li>保留了原文中的关键词，如Ceph、Quincy、Self Adm Agent、容器化、NFS、Kubernetes等。</li><li>优化了总结的条理性，使内容更加清晰易懂。</li><li>补充了会议的其他重要信息，如会议安排和特别感谢。</li></ol>",5)])])}const d=t(p,[["render",n]]);export{h as __pageData,d as default};
